const std = @import("std"); const builtin = @import("builtin"); const stor = @import("store");
const tkstorbase = @import("tk-stor-base.zig"); const CF = tkstorbase.CF; const CMDS_SCRI = tkstorbase.CMDS_SCRI; const ChaiStat = tkstorbase.ChaiStat; const DEFA_TMOZ_SECO = tkstorbase.DEFA_TMOZ_SECO; const FILE_NAME = tkstorbase.FILE_NAME; const Load = tkstorbase.Load; const MAXZ_CWDZ = tkstorbase.MAXZ_CWDZ; const MAXZ_FILE = tkstorbase.MAXZ_FILE; const MAXZ_IDSZ = tkstorbase.MAXZ_IDSZ; const MAXZ_LOCK = tkstorbase.MAXZ_LOCK; const MAXZ_PLUS_POOL = tkstorbase.MAXZ_PLUS_POOL; const MAXZ_RETR = tkstorbase.MAXZ_RETR; const MAXZ_RUNZ = tkstorbase.MAXZ_RUNZ; const MAXZ_TMOZ_SECO = tkstorbase.MAXZ_TMOZ_SECO; const NONE_SCHE = tkstorbase.NONE_SCHE; const PLUS_BIGZ = tkstorbase.PLUS_BIGZ; const PLUS_MAXZ = tkstorbase.PLUS_MAXZ; const Reje = tkstorbase.Reje; const STAT_DIRZ = tkstorbase.STAT_DIRZ; const TYPE_LIST = tkstorbase.TYPE_LIST; const Task = tkstorbase.Task; const WINZ_ONLY = tkstorbase.WINZ_ONLY; const autoIdenChec = tkstorbase.autoIdenChec; const chaiChec = tkstorbase.chaiChec; const idenVali = tkstorbase.idenVali; const norm = tkstorbase.norm; const scheNeed = tkstorbase.scheNeed; const taskPath = tkstorbase.taskPath; const typeChec = tkstorbase.typeChec; const winzOnlyChec = tkstorbase.winzOnlyChec; const tkstorvali = @import("tk-stor-vali.zig"); const plusRang = tkstorvali.plusRang; const vali = tkstorvali.vali;
fn chaiProb(task_list: []const Task, clai: []const []const u8, scri_okay: bool, chai: Task) ?[]const u8 { for (chai.ids orelse &.{}) |memb| { var foun: ?Task = null; for (task_list) |item| if (std.mem.eql(u8, item.id, memb)) { foun = item; break; }; if (foun) |mtas| { if (chaiChec(mtas)) return "ids: a chai cannot hold another chai"; } else { if (!autoIdenChec(memb)) return "ids: no job line, and the id is not valid for auto-run (use A-Z a-z 0-9 . _ -)"; if (!scri_okay) return "ids: an id has no job line, and the cmds script was not found"; } for (clai) |kept| if (std.mem.eql(u8, kept, memb)) return "ids: a job already belongs to another chai"; } return null; }
pub fn chaiBadzDrop(allo: std.mem.Allocator, keep: *std.ArrayList(Task), kidz: *std.ArrayList(usize), badz: *std.ArrayList(Reje), scri_okay: bool) void { var clai: std.ArrayList([]const u8) = .empty; var indx: usize = 0; while (indx < keep.items.len) { const task = keep.items[indx]; if (!chaiChec(task)) { indx += 1; continue; } if (chaiProb(keep.items, clai.items, scri_okay, task)) |whyz| { badz.append(allo, .{ .inde = kidz.items[indx], .iden = task.id, .whyz = whyz }) catch {}; _ = keep.orderedRemove(indx); _ = kidz.orderedRemove(indx); continue; } for (task.ids orelse &.{}) |memb| clai.append(allo, memb) catch {}; indx += 1; } }
pub fn chaiFind(task_list: []const Task, iden: []const u8) ?[]const u8 { for (task_list) |task| { if (!chaiChec(task)) continue; for (task.ids orelse &.{}) |memb| if (std.mem.eql(u8, memb, iden)) return task.id; } return null; }
